INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "欣欣小学组织三至五年级师生去春游，三年级138人、四年级164人、五年级152人。游乐园有两辆游览车：红色游览车限坐乘客168人，蓝色游览车限坐乘客294人。三个年级的师生一起坐上两辆游览车，座位够吗？按下面步骤解答：①先求（ ），列式：②再求（ ），列式：③比较：④答：", "options": null}', '①先求三个年级的总人数：138+164+152=454（人）；②再求两辆游览车的座位总数：168+294=462（个）；③比较：454<462；④答：座位够。', '先求出总人数 454 人，再求总座位数 462 个，总人数小于总座位数，所以座位够。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "欣欣小学三至五年级师生春游（三年级138人、四年级164人、五年级152人）要搭乘两辆游览车（红色限坐168人，蓝色限坐294人）。如果同年级的学生要在同一辆游览车上，应该怎么安排？", "options": null}', '三年级和五年级的师生坐蓝色游览车（138+152=290人<294人），四年级的师生坐红色游览车（164人<168人）。', '三年级138人+五年级152人=290人，不超过蓝车限坐294人；四年级164人不超过红车限坐168人。两种方案都不超载。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 1, '{"stem": "中秋假期，图书馆第一天接待读者234人，第二天上午接待读者178人，下午接待读者206人。两天一共接待读者多少人？", "options": null}', '618人', '234+178+206=618（人），两天共接待 618 人。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 1, '{"stem": "学校原来有680本练习本，发给学生478本，又买来350本。学校现在有多少本练习本？", "options": null}', '552本', '680−478+350=552（本），现在有 552 本。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "周末，爸爸去家具店给小海买桌椅。一把椅子要320元，比一张书桌便宜192元。买这样一套桌椅要多少元？", "options": null}', '832元', '书桌价钱：320+192=512（元）；一套：320+512=832（元）。综合算式：320+192+320=832。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "乐乐一家去商场购物：上衣每件256元，裤子每条107元，运动鞋每双398元。（1）妈妈买了一件上衣和一条裤子，付了400元，找回多少元？", "options": null}', '37元', '400−256−107=37（元），应找回 37 元。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "乐乐一家去商场购物：上衣每件256元，裤子每条107元，运动鞋每双398元。（2）运动鞋促销：买两双减100元。爸爸买了两双，一共要付多少元？", "options": null}', '696元', '两双原价：398×2=796（元）；减100元后：796−100=696（元）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "乐乐一家去商场购物：上衣每件256元，裤子每条107元，运动鞋每双398元（买两双减100元，爸爸买两双付696元）。（3）商场迎国庆促销：购物每满500元可参加一次抽奖。乐乐一家这次消费的金额，可以有几次抽奖机会？", "options": null}', '2次', '消费总额：256+107+696=1059（元）。每满500元抽一次：500×2=1000<1059<1500，1059÷500=2（次）……59（元），所以有 2 次抽奖机会。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "水果店里的生梨比苹果少51只，苹果比橘子少29只。生梨和橘子相差多少只？", "options": null}', '80只', '把苹果的只数看作中间量：生梨比苹果少51只，橘子比苹果多29只，所以生梨和橘子相差 51+29=80（只）。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.3"]', NULL, 0);
